const now = new Date();
const targetDate = new Date();
targetDate.setDate(now.getDate() - 3);
const targetStr = targetDate.toISOString().slice(0, 10);

const items = $input.all().map(i => i.json).filter(b => String(b.date || '').slice(0, 10) === targetStr && !b.vipCouponSent);

return items.map(item => ({
  json: {
    bookingId: item.bookingId,
    customerName: item.customerName || 'Viajero',
    customerEmail: item.customerEmail,
    vipCode: `PURAVIDA15-${item.bookingId.slice(-6)}`,
    mensaje: `¡Hola ${item.customerName || 'Viajero'}! Esperamos que hayas disfrutado al máximo tu experiencia con Costa Rica Tours. Como agradecimiento por tu confianza, queremos regalarte un 15% de descuento VIP (Código: PURAVIDA15-${item.bookingId.slice(-6)}) para tu próxima visita a nuestro hermoso país. ¡Te esperamos pronto con los brazos abiertos! 🌿✨`
  }
}));
